'use strict';
/*
 * SG Data Pack extraction config for saga.js (t03 multi-stage fixture)
 *
 * Multi-stage pattern:
 *   - Entities (chars) are shared across stages.
 *   - Edges are split into stage1Edges / stage2Edges.
 *   - The same (hero,ally) pair has DIFFERENT relationship types per stage
 *     (alliance vs rivalry), so each master edge carries a `scope` array to
 *     satisfy E12 disambiguation.
 *   - Master `relations` = union of per-stage edges (deduped); provenance
 *     relations keys use `a::b` deduped by pair.
 *   - `stages` declares both stages with entity membership + per-stage relation refs.
 */

const path = require('path');
const LIB_DIR = path.resolve(__dirname);

// Sort key for edges so the equivalence comparison is order-insensitive.
const edgeKey = (e) => e.a + '::' + e.b + '::' + e.type;

module.exports = {
  libId: 'saga',
  libDir: LIB_DIR,
  engineFile: 'lib/src/saga.js',
  globalName: 'Saga',
  schemaVersion: '1.2',

  literals: [
    { key: 'chars', pattern: /var chars = \(options && options\.chars\) \|\|/ },
    { key: 'stage1Edges', pattern: /var stage1Edges = \(options && options\.stage1Edges\) \|\|/ },
    { key: 'stage2Edges', pattern: /var stage2Edges = \(options && options\.stage2Edges\) \|\|/ }
  ],

  meta: {
    title: 'Saga — multi-stage narrative',
    hero: 'hero',
    source: 'Embedded data from original case page (decomposition export)',
    fetchedAt: new Date().toISOString().slice(0, 10)
  },

  buildPack(defaults) {
    // ① Entity table: chars already keyed by stable id; add kind (already present).
    const entities = {};
    for (const [id, c] of Object.entries(defaults.chars)) {
      entities[id] = { name: c.name, kind: c.kind };
    }

    // ② Alias table: display name -> id (crawl-normalization entry point).
    const aliases = {};
    for (const [id, c] of Object.entries(defaults.chars)) aliases[c.name] = id;

    // ③ Relationship-type registry (all enum values used by the engine).
    const relationTypes = {
      alliance: { label: 'Alliance', color: '#4b8b4b' },
      rivalry: { label: 'Rivalry', color: '#d9a44b' },
      conflict: { label: 'Conflict', color: '#d94b4b' }
    };

    // ④ Master edge list = UNION of per-stage edges.
    //    The (hero,ally) pair appears twice with different types; each edge is
    //    tagged with a `scope` array naming the stage it is active in, so E12
    //    disambiguation passes (a stage {a,b} ref resolves to exactly one edge
    //    via scope).
    const relations = [];
    defaults.stage1Edges.forEach(function (e) {
      relations.push({ a: e.a, b: e.b, type: e.type, label: relationTypes[e.type].label, scope: ['stage1'] });
    });
    defaults.stage2Edges.forEach(function (e) {
      relations.push({ a: e.a, b: e.b, type: e.type, label: relationTypes[e.type].label, scope: ['stage2'] });
    });

    // ⑤ Stages: declare both stages with entity membership + per-stage relation refs.
    //    Relations reference master edges by {a,b}; never duplicate edge fields.
    const stage1Members = Object.keys(entities);
    const stage2Members = Object.keys(entities);
    const stages = [
      {
        key: 'stage1',
        name: 'Stage One',
        desc: 'The alliance era — hero and ally stand together.',
        entities: stage1Members,
        relations: defaults.stage1Edges.map(function (e) { return { a: e.a, b: e.b }; })
      },
      {
        key: 'stage2',
        name: 'Stage Two',
        desc: 'The schism — hero and ally clash, and the foe enters.',
        entities: stage2Members,
        relations: defaults.stage2Edges.map(function (e) { return { a: e.a, b: e.b }; })
      }
    ];

    const pack = {
      entities: entities,
      aliases: aliases,
      relationTypes: relationTypes,
      relations: relations,
      stages: stages,
      domain: {}
    };

    // ⑥ Provenance stamping (mandatory in v1.2).
    //    relations keys use `a::b` deduped by pair (hero::ally appears once).
    const stamp = function (origin) {
      return {
        origin: origin,
        sourceUrl: null,
        fetchedAt: new Date().toISOString().slice(0, 10),
        confidence: 1.0,
        note: 'Baseline data (embedded in original case page); original sourceUrl lost'
      };
    };
    pack.provenance = {
      entities: Object.fromEntries(Object.keys(pack.entities).map(function (id) { return [id, stamp('engine-embedded-defaults')]; })),
      relations: Object.fromEntries(
        pack.relations
          .map(function (r) { return r.a + '::' + r.b; })
          .filter(function (k, i, arr) { return arr.indexOf(k) === i; })
          .map(function (k) { return [k, stamp('engine-embedded-defaults')]; })
      )
    };

    return pack;
  },

  // Losslessness: __fromPack(pack) returns {chars, stage1AllEdges, stage2AllEdges};
  // compare against the sliced defaults {chars, stage1Edges, stage2Edges}.
  equivalence: [
    { lit: 'chars', from: 'chars' },
    { lit: 'stage1Edges', from: 'stage1AllEdges' },
    { lit: 'stage2Edges', from: 'stage2AllEdges' }
  ],

  // Edges are reconstructed by scope-filtering the master list, so compare
  // order-insensitively.
  sortKeys: {
    stage1Edges: function (x, y) { return edgeKey(x).localeCompare(edgeKey(y)); },
    stage2Edges: function (x, y) { return edgeKey(x).localeCompare(edgeKey(y)); }
  },

  domainSchema: {
    type: 'object',
    description: 'Library-specific data collections (none for this fixture)',
    additionalProperties: true
  }
};

'use strict';
/*
 * saga.js - multi-stage narrative engine (synthetic t03 fixture)
 *
 * Two stages share the same entities but relationships evolve across stages
 * (E12: multiple edges on the same (a,b) pair must be disambiguated by scope).
 */
var Saga = (function () {
  var options = (typeof options !== 'undefined') ? options : undefined;
  var chars = (options && options.chars) || {
    hero: { name: 'Hero', kind: 'person' },
    ally: { name: 'Ally', kind: 'person' },
    foe: { name: 'Foe', kind: 'person' }
  };
  // Stage 1 edges
  var stage1Edges = (options && options.stage1Edges) || [
    { a: 'hero', b: 'ally', type: 'alliance' }
  ];
  // Stage 2 edges (hero & ally now conflict, hero & foe fight)
  var stage2Edges = (options && options.stage2Edges) || [
    { a: 'hero', b: 'ally', type: 'rivalry' },
    { a: 'hero', b: 'foe', type: 'conflict' }
  ];

  /* ============ SG Data Pack support ============ */
  function __fromPack(pack) {
    var p = pack || {};
    var restoredChars = {};
    Object.keys(p.entities || {}).forEach(function (id) {
      restoredChars[id] = { name: p.entities[id].name, kind: p.entities[id].kind };
    });
    // Reconstruct per-stage edges from the scope field (scope is an array of stage keys)
    var s1 = [], s2 = [];
    (p.relations || []).forEach(function (r) {
      var edge = { a: r.a, b: r.b, type: r.type };
      var scopes = Array.isArray(r.scope) ? r.scope : (r.scope ? [r.scope] : []);
      if (scopes.indexOf('stage1') !== -1) s1.push(edge);
      if (scopes.indexOf('stage2') !== -1) s2.push(edge);
    });
    return { chars: restoredChars, stage1AllEdges: s1, stage2AllEdges: s2 };
  }
  function __resolveDataOptions(options) {
    if (!options || !options.data) return options;
    if (typeof SGDataLoader !== 'undefined') {
      SGDataLoader.assertValid(options.data); // fail loudly, never silently
    } else if (typeof console !== 'undefined' && console.error) {
      console.error('[engine] options.data not validated: include lib/src/sg-data-loader.js first');
    }
    var d = __fromPack(options.data);
    var merged = {};
    Object.keys(options).forEach(function (k) { merged[k] = options[k]; });
    // pack wins: map fromPack outputs back onto the legacy option keys
    if (d.chars !== undefined) merged.chars = d.chars;
    if (d.stage1AllEdges !== undefined) merged.stage1Edges = d.stage1AllEdges;
    if (d.stage2AllEdges !== undefined) merged.stage2Edges = d.stage2AllEdges;
    return merged;
  }
  /* ========== SG Data Pack support (end) ========== */

  function mount(root, options) {
    options = __resolveDataOptions(options); // first line - prefer injected Data Pack
    return {
      chars: (options && options.chars) || chars,
      stage1Edges: (options && options.stage1Edges) || stage1Edges,
      stage2Edges: (options && options.stage2Edges) || stage2Edges
    };
  }

  return { mount: mount, __fromPack: __fromPack, __resolveDataOptions: __resolveDataOptions };
})();

if (typeof globalThis !== 'undefined') globalThis.Saga = Saga;

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://sg.local/data-pack.schema.json",
  "title": "SG Data Pack v1.2 — Unified Data Contract for Component Libraries",
  "description": "The single entry point for business data of all sg-* component libraries. Globally unique entities, id references, stages that reference rather than duplicate. Runtime validation is performed by sg-data-loader.js (rules E1-E15/W1-W6 correspond one-to-one with the rules below); this file is the formal contract. v1.1 added: relations.scope, attributeTypes/attributeSources, contents, assets hash, meta.assetBase, kindNameFields. v1.2 added: sameAs (entity identity), provenance (record-level provenance as a parallel section that never invades entity bodies — zero engine changes), meta.confidenceThreshold, W6 fuzzy duplicate detection.",
  "type": "object",
  "required": [
    "schemaVersion",
    "meta",
    "entities"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "enum": [
        "1.0",
        "1.1",
        "1.2",
        "1.3"
      ]
    },
    "meta": {
      "type": "object",
      "required": [
        "id",
        "title"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "description": "Library identifier, matching the directory name"
        },
        "title": {
          "type": "string",
          "minLength": 1
        },
        "hero": {
          "type": "string",
          "description": "Core entity id (graph center / protagonist); must exist in entities"
        },
        "source": {
          "type": "string",
          "description": "Data source (crawl-source annotation)"
        },
        "fetchedAt": {
          "type": "string",
          "description": "Fetch date, YYYY-MM-DD"
        },
        "generatedBy": {
          "type": "string",
          "description": "Extraction-script path (@generated marker)"
        },
        "assetBase": {
          "type": "string",
          "description": "Resolution prefix for bare-filename assets (e.g. '../assets/'); once declared, 'x.png' in the data resolves and registers as assetBase+'x.png'"
        },
        "confidenceThreshold": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "(v1.2) Low-confidence warning threshold; default 0.7"
        }
      },
      "additionalProperties": true
    },
    "kindNameFields": {
      "type": "object",
      "description": "kind -> name-field mapping (e.g. {work: 'title'}); kinds not declared here default to the name field",
      "additionalProperties": {
        "type": "string"
      }
    },
    "sameAs": {
      "type": "array",
      "description": "(v1.2) Entity-identity declarations: [[idA, idB], ...] means two entities refer to the same real-world subject (e.g. Ying Zheng ↔ Qin Shi Huang). Once declared, W6 no longer flags the pair; downstream dedup/aggregation relies on this.",
      "items": {
        "type": "array",
        "prefixItems": [
          {
            "type": "string"
          },
          {
            "type": "string"
          }
        ],
        "minItems": 2,
        "maxItems": 2
      }
    },
    "provenance": {
      "type": "object",
      "description": "(v1.2) Record-level provenance (parallel-section design: never embedded into entities/relations/contents bodies, so engines need no changes). Each group's keys point at the corresponding records; confidence below meta.confidenceThreshold triggers a W5 low-confidence warning.",
      "properties": {
        "entities": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        },
        "relations": {
          "type": "object",
          "description": "Key format: 'a::b' (entity-id pair)",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        },
        "contents": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/provEntry"
          }
        }
      },
      "additionalProperties": false
    },
    "entities": {
      "type": "object",
      "minProperties": 1,
      "description": "Global entity table. Keys are stable ids (semantic slugs); values preserve all business fields of the entity. Referencing by name or array index is forbidden.",
      "patternProperties": {
        "^[a-z][a-z0-9_-]*$": {
          "type": "object",
          "required": [
            "name",
            "kind"
          ],
          "properties": {
            "name": {
              "type": "string",
              "minLength": 1,
              "description": "Display name (may be Chinese; for display only, never a reference key)"
            },
            "kind": {
              "type": "string",
              "minLength": 1,
              "description": "Entity kind: person / work / term / event / ..."
            }
          },
          "additionalProperties": true
        }
      },
      "additionalProperties": false
    },
    "aliases": {
      "type": "object",
      "description": "Crawled name / variant spelling -> canonical id. The normalization entry point on the data-production side; resolvable at runtime via SGDataLoader.resolveId.",
      "additionalProperties": {
        "type": "string",
        "description": "Must be an id present in entities"
      }
    },
    "relationTypes": {
      "type": "object",
      "description": "Relationship-type registry (enum + display attributes). Every relations[].type must be registered here.",
      "additionalProperties": {
        "type": "object",
        "required": [
          "label"
        ],
        "properties": {
          "label": {
            "type": "string"
          },
          "color": {
            "type": "string",
            "description": "Color value or CSS variable reference"
          }
        },
        "additionalProperties": true
      }
    },
    "heroRelTypes": {
      "type": "object",
      "description": "(optional, Plan-B dual registry) Relationship-type registry for the hero-radial dimension (person -> core). When overlay.rel / heroRel and relations[].type are semantically different dimensions, register them separately here and in relationTypes, with library-level rules forbidding cross-dimension use (e.g. qinshihuang: overlay.rel in {ruler, family, enemy})",
      "additionalProperties": {
        "type": "object",
        "required": [
          "label"
        ],
        "properties": {
          "label": {
            "type": "string"
          },
          "color": {
            "type": "string"
          },
          "dimension": {
            "type": "string",
            "enum": [
              "hero-radial",
              "pairwise",
              "both"
            ]
          }
        },
        "additionalProperties": true
      }
    },
    "relations": {
      "type": "array",
      "description": "Master edge list; each edge is stored exactly once. Stages reference edges via {a,b}; duplication is forbidden. When multiple edges share the same (a,b) pair (relationship evolves across stages), scope or type must make references resolvable.",
      "items": {
        "type": "object",
        "required": [
          "a",
          "b",
          "type"
        ],
        "properties": {
          "a": {
            "type": "string",
            "description": "Entity id (or a crawled name from aliases, normalized during validation)"
          },
          "b": {
            "type": "string"
          },
          "type": {
            "type": "string",
            "description": "Must be registered in relationTypes"
          },
          "label": {
            "type": "string"
          },
          "scope": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "minItems": 1,
            "description": "(v1.1) This edge is only active in the listed stages (values are stages[].key). Without scope, the edge is active in all stages"
          }
        },
        "additionalProperties": true
      }
    },
    "stages": {
      "type": "array",
      "description": "Stage/scene/event views. Carry only id references and stage-specific overlays; embedding entity fields is forbidden.",
      "items": {
        "type": "object",
        "required": [
          "key",
          "name",
          "entities"
        ],
        "properties": {
          "key": {
            "type": "string",
            "minLength": 1
          },
          "name": {
            "type": "string",
            "minLength": 1
          },
          "desc": {
            "type": "string"
          },
          "descMobile": {
            "type": "string"
          },
          "entities": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Subset of entity ids for this stage"
          },
          "layout": {
            "type": "object",
            "description": "Normalized coordinates keyed by entity id",
            "additionalProperties": {
              "type": "array",
              "prefixItems": [
                {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1
                },
                {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1
                }
              ],
              "minItems": 2,
              "maxItems": 2
            }
          },
          "relations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "a",
                "b"
              ],
              "properties": {
                "a": {
                  "type": "string"
                },
                "b": {
                  "type": "string"
                }
              },
              "additionalProperties": false
            },
            "description": "{a,b} keys referencing master relations; type/label come from the master edge"
          },
          "overlay": {
            "type": "object",
            "description": "Stage-specific information (persona/description overrides), keyed by entity id",
            "additionalProperties": {
              "type": "object"
            }
          }
        },
        "additionalProperties": true
      }
    },
    "attributeTypes": {
      "type": "object",
      "description": "(v1.1) Attribute-label registry (symmetric to relationTypes). Labels in the attribute-pair collections declared by attributeSources must be registered here.",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "label": {
            "type": "string"
          },
          "description": {
            "type": "string"
          }
        },
        "additionalProperties": true
      }
    },
    "attributeSources": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "(v1.1) Path declarations of attribute-pair collections; supports 'entities.*.<field>' and 'domain.<path>'. Every [label, value, ...] pair or {label, ...} object in the declared collections has its label checked by E10"
    },
    "contents": {
      "type": "object",
      "description": "(v1.1) Long-form content data layer: prose/timeline lifted out of template HTML. body is a restricted HTML subset; highlights declare in-text entity/annotation references (checked by E13 — a wrong entity name in prose is caught).",
      "additionalProperties": {
        "type": "object",
        "required": [
          "kind"
        ],
        "properties": {
          "kind": {
            "type": "string",
            "description": "Content kind: timeline-item / article-section / ..."
          },
          "title": {
            "type": "string"
          },
          "body": {
            "type": "string",
            "description": "Restricted-HTML-subset string"
          },
          "bodyFormat": {
            "type": "string",
            "enum": [
              "html-subset",
              "text"
            ]
          },
          "highlights": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "ref"
              ],
              "properties": {
                "text": {
                  "type": "string"
                },
                "ref": {
                  "type": "string",
                  "description": "Entity id / alias / domain.notes annotation key"
                }
              },
              "additionalProperties": true
            }
          }
        },
        "additionalProperties": true
      }
    },
    "domain": {
      "type": "object",
      "description": "Library-specific data collections (works/questions/cast/notes, etc.), constrained by each library's own data.schema.json"
    },
    "assets": {
      "type": "object",
      "description": "Asset manifest; keys are asset paths as they appear in the data",
      "additionalProperties": {
        "type": "object",
        "properties": {
          "sourceUrl": {
            "type": "string"
          },
          "hash": {
            "type": "string"
          },
          "exists": {
            "type": "boolean"
          },
          "bytes": {
            "type": "integer"
          }
        },
        "additionalProperties": true
      }
    },
    "derivations": {
      "type": "object",
      "description": "v1.3 派生契约：声明哪些呈现是从 pack 数据派生的、怎么派生、谁消费。文档化契约（非可执行代码），只建模非平凡派生（重复/排序/重建/消解/投影）。",
      "additionalProperties": {
        "type": "object",
        "required": [
          "kind",
          "source",
          "consumers",
          "note"
        ],
        "properties": {
          "kind": {
            "enum": [
              "repeat",
              "insertion-order",
              "lookup-rebuild",
              "scope-resolution",
              "projection",
              "reference-only"
            ],
            "description": "派生类型：repeat=集合重复渲染；insertion-order=键插入序即呈现序；lookup-rebuild=按字段反查重建；scope-resolution=方向/作用域消解；projection=字段直投但有重组；reference-only=仅存引用运行时重建"
          },
          "source": {
            "type": "string",
            "description": "派生源的 pack 内路径（如 domain.carouselTrack.entityIds / contents / entities.*.name）"
          },
          "consumers": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "消费方标识：引擎函数名或组件文件"
          },
          "affects": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "（可选）受影响的呈现区域/选择器"
          },
          "note": {
            "type": "string",
            "description": "人读说明：派生怎么工作、变更时的影响面"
          },
          "alsoTouches": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "（可选）次级影响源：除 source 外，变更这些路径也会影响此派生。用于 source 描述组合关系、但实体字段变更也影响呈现的情况（如 carouselTrack.source=domain.carouselTrack.entityIds，但 milestone.title 变更也影响渲染）。"
          }
        }
      }
    }
  },
  "$defs": {
    "provEntry": {
      "type": "object",
      "properties": {
        "origin": {
          "type": "string",
          "description": "Data origin: engine-embedded-defaults / example-json-contract / template-html-contents / crawl:<source> etc."
        },
        "sourceUrl": {
          "type": [
            "string",
            "null"
          ],
          "description": "Original source URL (mandatory for crawl pipelines)"
        },
        "fetchedAt": {
          "type": "string",
          "description": "Fetch date, YYYY-MM-DD"
        },
        "confidence": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "description": "Confidence; baseline data (original case page) is 1.0, crawled data gets actual values from the pipeline"
        },
        "note": {
          "type": "string"
        }
      },
      "additionalProperties": true
    }
  }
}

